"""Per-turn budgets of the agent loop (design §4.8): LLM steps, tool calls, tokens, wall time.

`AgentBudget` is the configuration (defaults below, env overrides validated by `from_env`).
`BudgetTracker` is one turn's tally. The loop asks it before every LLM step (`stop_before_step`)
and before every tool call (`admit_tool_call`); it never executes anything itself.

Token accounting is a **soft** cap and not a dollar cap:
- the provider's `usage.total_tokens` of a call is only known after the call, so the check runs
  between LLM requests: a turn that crosses the cap finishes the call in flight and starts no
  further step;
- a call (failed or completed) that reports no usage is charged a conservative estimate:
  `ceil(request characters / CHARS_PER_TOKEN_ESTIMATE) + max_output_tokens_per_call`
  (every character of the request counted as half a token, plus the whole output allowance);
- retries are separate calls and are charged too.
"""
from __future__ import annotations

import json
import math
import os
from dataclasses import dataclass, fields
from typing import Any, Mapping

CHARS_PER_TOKEN_ESTIMATE = 2  # conservative: English text and JSON average about 3-4 characters per token

# name -> (environment variable, lowest, highest). Bounds keep a typo from removing a budget
# (0 or a huge number) or from making every turn fail.
_BOUNDS: dict[str, tuple[str, float, float]] = {
    "max_steps": ("AGENT_MAX_STEPS", 1, 20),
    "max_tool_calls_per_step": ("AGENT_MAX_TOOL_CALLS_PER_STEP", 1, 16),
    "max_tool_calls_per_turn": ("AGENT_MAX_TOOL_CALLS_PER_TURN", 1, 64),
    "max_output_tokens_per_call": ("AGENT_MAX_OUTPUT_TOKENS_PER_CALL", 256, 32_768),
    "max_total_tokens_per_turn": ("AGENT_MAX_TOTAL_TOKENS_PER_TURN", 1_000, 1_000_000),
    "max_turn_seconds": ("AGENT_MAX_TURN_SECONDS", 5, 600),
}


@dataclass(frozen=True)
class AgentBudget:
    max_steps: int = 6  # LLM steps (calls that complete, not counting retries) per turn
    max_tool_calls_per_step: int = 4  # executed tool calls of one completion
    max_tool_calls_per_turn: int = 12  # executed tool calls of the whole turn
    max_output_tokens_per_call: int = 4096  # the request's max_tokens (includes thinking tokens)
    max_total_tokens_per_turn: int = 20_000  # soft: provider-reported total tokens of all calls
    max_turn_seconds: float = 90.0  # the whole turn: LLM calls, tools, retries

    def __post_init__(self) -> None:
        for f in fields(self):
            value = getattr(self, f.name)
            whole = f.name != "max_turn_seconds"
            if isinstance(value, bool) or not isinstance(value, (int, float)) \
                    or (whole and not isinstance(value, int)) or not math.isfinite(value) or value <= 0:
                raise ValueError(f"{f.name} must be a positive {'integer' if whole else 'number'}, got {value!r}")

    def checked(self) -> "AgentBudget":
        """The same budget, also within the bounds the environment may set (startup check)."""
        for name, (var, low, high) in _BOUNDS.items():
            value = getattr(self, name)
            if not low <= value <= high:
                raise ValueError(f"{var} must be between {low:g} and {high:g}, got {value:g}")
        return self

    @classmethod
    def from_env(cls, env: Mapping[str, str] | None = None) -> "AgentBudget":
        """Defaults, overridden by the `AGENT_*` variables of `_BOUNDS`. A value that is not a
        number or is out of bounds raises ValueError (the app does not start with a bad budget)."""
        env = os.environ if env is None else env
        values: dict[str, Any] = {}
        for name, (var, low, high) in _BOUNDS.items():
            raw = (env.get(var) or "").strip().replace("_", "")
            if not raw:
                continue
            try:
                value = float(raw) if name == "max_turn_seconds" else int(raw)
            except ValueError:
                raise ValueError(f"{var} must be {'a number' if name == 'max_turn_seconds' else 'an integer'}, "
                                 f"got {raw!r}") from None
            if not low <= value <= high:  # also catches nan
                raise ValueError(f"{var} must be between {low:g} and {high:g}, got {raw!r}")
            values[name] = value
        return cls(**values).checked()


def estimate_tokens(messages: Any, max_output_tokens: int) -> int:
    """Conservative charge for a call without reported usage (see the module docstring)."""
    chars = len(json.dumps(messages, ensure_ascii=False, separators=(",", ":"), default=str))
    return math.ceil(chars / CHARS_PER_TOKEN_ESTIMATE) + max_output_tokens


def reported_tokens(usage: Any) -> int | None:
    """`usage.total_tokens` when the provider reported a usable one."""
    total = usage.get("total_tokens") if isinstance(usage, dict) else None
    if isinstance(total, bool) or not isinstance(total, int) or total < 0:
        return None
    return total


class BudgetTracker:
    """One turn's use of an `AgentBudget`. Not thread-safe; owned by the turn's task."""

    def __init__(self, budget: AgentBudget):
        self.budget = budget
        self.steps = 0  # LLM steps started
        self.tool_calls = 0  # tool calls executed (refused ones not counted)
        self.refused_calls = 0
        self.tokens = 0  # reported + estimated
        self.estimated_calls = 0  # calls charged by estimate
        self._step_calls = 0

    # ---------------------------------------------------------------- LLM steps ------------
    def stop_before_step(self) -> dict | None:
        """None when another LLM step may start (and counts it), else the fallback problem."""
        if self.steps >= self.budget.max_steps:
            return {"kind": "max_steps", "value": str(self.budget.max_steps)}
        if self.tokens >= self.budget.max_total_tokens_per_turn:
            return {"kind": "token_budget", "value": str(self.budget.max_total_tokens_per_turn)}
        self.steps += 1
        self._step_calls = 0
        return None

    def charge(self, usage: Any, request_messages: Any) -> tuple[int, bool]:
        """Count one LLM call (completed, failed or retried). Returns (tokens charged, estimated)."""
        total = reported_tokens(usage)
        if total is None:
            total = estimate_tokens(request_messages, self.budget.max_output_tokens_per_call)
            self.estimated_calls += 1
            self.tokens += total
            return total, True
        self.tokens += total
        return total, False

    # ---------------------------------------------------------------- tool calls -----------
    def admit_tool_call(self) -> str | None:
        """None when one more tool call of the current step may run (and counts it), else why
        not: "per_step" or "per_turn". A refused call is never executed."""
        if self.tool_calls >= self.budget.max_tool_calls_per_turn:
            reason = "per_turn"
        elif self._step_calls >= self.budget.max_tool_calls_per_step:
            reason = "per_step"
        else:
            self.tool_calls += 1
            self._step_calls += 1
            return None
        self.refused_calls += 1
        return reason

    @property
    def tool_calls_left(self) -> int:
        return self.budget.max_tool_calls_per_turn - self.tool_calls

    def snapshot(self) -> dict:
        """For logs and the llm_calls record (no secrets, small)."""
        return {"steps": self.steps, "tool_calls": self.tool_calls, "refused_calls": self.refused_calls,
                "tokens": self.tokens, "estimated_calls": self.estimated_calls}


def refusal(reason: str, budget: AgentBudget) -> dict:
    """The tool result of a call that was not executed (the LLM protocol needs one per call)."""
    if reason == "per_step":
        message = (f"Not executed: at most {budget.max_tool_calls_per_step} tool calls are run per step. "
                   "Call the remaining tools again in a later step if they are still needed.")
    else:
        message = (f"Not executed: this turn has used all {budget.max_tool_calls_per_turn} tool calls. "
                   "Answer with the results you already have.")
    return {"code": "tool_budget_exceeded", "message": message, "limit": reason}
"""All endpoints of docs/api/contract.md except the message stream (501 until T3 is merged)."""
from __future__ import annotations

import asyncio
import hmac
import json
import logging
import math

from fastapi import APIRouter, Depends, FastAPI, Request
from fastapi.responses import JSONResponse, StreamingResponse
from typing import Annotated

from pydantic import AfterValidator, BaseModel

from ..agent import Agent, LLMConfig, LLMNotConfigured, OpenAIChatClient, encode_stream
from ..agent.loop import MAX_USER_CHARS, TITLE_CHARS
from ..agent.sse import HEADERS as SSE_HEADERS, MEDIA_TYPE as SSE_MEDIA_TYPE
from ..airline import Airline, NotFound
from ..core.network import NetworkProvider
from ..store import Store
from . import session
from .google import MAX_TOKEN_CHARS, GoogleVerifier, InvalidToken, KeysUnavailable
from .logins import InviteCodes, Throttle, clean_name, client_ip, throttle_key
from .errors import ApiError, install_handlers, respond
from .guards import ApiGuard
from .limits import reserve_message, usage_view
from .settings import SESSION_TTL_SECONDS, Settings

PING_COUNT = 5
NEW_CONVERSATION_TITLE = "New conversation"
GOOGLE_NAME_MAX = 80

log = logging.getLogger(__name__)


# Field bounds (review #11): oversized values are a 400 before any hashing or lookup. The message
# text bound is generous; the agent's own MAX_USER_CHARS check keeps its specific message.
# (An after-validator, not Field(max_length): pydantic's constraint path refuses lone surrogates,
# which must stay a wrong login, not a 400.)
SHORT_FIELD = 200


def _bounded(limit: int):
    def check(value: str) -> str:
        if len(value) > limit:
            raise ValueError("too long")
        return value
    return Annotated[str, AfterValidator(check)]


class Credentials(BaseModel):
    username: _bounded(SHORT_FIELD)
    password: _bounded(SHORT_FIELD)


class GoogleCredential(BaseModel):
    credential: _bounded(MAX_TOKEN_CHARS)


class Invite(BaseModel):
    code: _bounded(SHORT_FIELD)
    name: _bounded(SHORT_FIELD)


class Text(BaseModel):
    text: _bounded(4 * MAX_USER_CHARS)


class Nonce(BaseModel):
    nonce: _bounded(SHORT_FIELD)


def login_enabled(request: Request, user: dict) -> bool:
    """Is the way this user signed in still switched on? (review #7: turning dev login off or
    removing an invite code ends those sessions, not only new logins)"""
    s: Settings = request.app.state.settings
    provider = user["auth_provider"]
    if provider == "dev":
        return s.dev_login  # renaming DEV_AUTH_USER does not end the old user's sessions: rotate SESSION_SECRET
    if provider == "invite":
        return request.app.state.invite_codes.active(user["provider_sub"])
    if provider == "google":
        return request.app.state.google is not None
    return False


def current_user(request: Request) -> dict:
    """The signed-in user, or 401. The cookie names the user and its session epoch; the row must
    still exist, the epoch must be current (not logged out since) and the login method enabled."""
    s: Settings = request.app.state.settings
    sess = session.verify(s.session_secret, request.cookies.get(session.COOKIE))
    user = request.app.state.store.get_user(sess.user_id) if sess else None
    if user is None or user["session_epoch"] != sess.epoch or not login_enabled(request, user):
        raise ApiError(401, "unauthorized", "Please sign in.")
    return user


def _octets(text: str) -> bytes:
    return text.encode("utf-8", "surrogatepass")


def user_view(user: dict) -> dict:
    return {"id": user["id"], "display_name": user["display_name"], "auth_provider": user["auth_provider"],
            "email": user["email"]}


def summary_view(store: Store, user_id: str, summary: dict) -> dict:
    """Contract: the title is never empty — first user message, else "New conversation"."""
    if summary["title"].strip():
        return summary
    first = " ".join(store.first_user_text(user_id, summary["id"]).split())[:TITLE_CHARS]
    return {**summary, "title": first or NEW_CONVERSATION_TITLE}


def throttle_login(request: Request) -> None:
    """Login endpoints: at most N attempts per client IP per minute (contract), else 429."""
    s: Settings = request.app.state.settings
    ip = client_ip(request.client.host if request.client else None, request.headers, s.trusted_proxies,
                   s.trust_cf_connecting_ip)
    wait = request.app.state.login_throttle.hit(throttle_key(ip))
    if wait is not None:
        raise ApiError(429, "rate_limited", "Too many sign-in attempts. Please wait a minute and try again.",
                       headers={"Retry-After": str(max(1, math.ceil(wait)))})


def _signed_in(settings: Settings, user: dict) -> JSONResponse:
    response = JSONResponse(user_view(user))
    _set_cookie(response, settings, user["id"], user["session_epoch"])
    return response


def _set_cookie(response, settings: Settings, user_id: str, epoch: int) -> None:
    response.set_cookie(session.COOKIE, session.issue(settings.session_secret, user_id, SESSION_TTL_SECONDS,
                                                      epoch=epoch),
                        max_age=SESSION_TTL_SECONDS, httponly=True, samesite="lax",
                        secure=settings.cookie_secure, path="/")


def build_router() -> APIRouter:
    r = APIRouter(prefix="/api")

    @r.get("/health")
    def health(request: Request) -> dict:
        net = request.app.state.networks.current()
        return {"status": "ok", "network_fingerprint": net.fingerprint.id}

    @r.get("/config")
    def config(request: Request) -> dict:
        s: Settings = request.app.state.settings
        return {"dev_login": s.dev_login, "invite_login": s.invite_login, "google_client_id": s.google_client_id}

    @r.post("/auth/dev")
    def auth_dev(creds: Credentials, request: Request):
        s: Settings = request.app.state.settings
        if not s.dev_login:
            raise ApiError(404, "not_found", "Not found.")
        throttle_login(request)
        # surrogatepass: a lone surrogate in the JSON must be a wrong password, not a 500
        ok = s.dev_login and hmac.compare_digest(_octets(creds.username), _octets(s.dev_user)) \
            & hmac.compare_digest(_octets(creds.password), _octets(s.dev_password))
        if not ok:
            raise ApiError(401, "invalid_credentials", "Wrong username or password.")
        user = request.app.state.store.upsert_user("dev", s.dev_user, s.dev_user)
        return _signed_in(s, user)

    @r.post("/auth/google")
    def auth_google(body: GoogleCredential, request: Request):
        s: Settings = request.app.state.settings
        verifier: GoogleVerifier | None = request.app.state.google
        if verifier is None:
            raise ApiError(404, "not_found", "Not found.")
        throttle_login(request)
        try:
            who = verifier.verify(body.credential)
        except KeysUnavailable:
            raise ApiError(503, "auth_unavailable",
                           "Google sign-in is unavailable right now. Please try again later.") from None
        except InvalidToken as e:
            log.info("google sign-in rejected: %s", e)  # the reason only, never the token
            raise ApiError(401, "invalid_credentials", "Google sign-in could not be verified.") from None
        name = " ".join((who.name or who.email or "Google user").split())[:GOOGLE_NAME_MAX] or "Google user"
        user = request.app.state.store.upsert_user("google", who.sub, name, who.email)
        return _signed_in(s, user)

    @r.post("/auth/invite")
    def auth_invite(body: Invite, request: Request):
        s: Settings = request.app.state.settings
        codes: InviteCodes = request.app.state.invite_codes
        if not codes:
            raise ApiError(404, "not_found", "Not found.")
        throttle_login(request)
        key = codes.match(body.code)
        if key is None:
            raise ApiError(401, "invalid_credentials", "That invite code is not valid.")
        name = clean_name(body.name)
        if name is None:
            raise ApiError(400, "bad_request", "The name must be 1–40 characters.")
        # one account per code; the name is only the display name (refreshed on every login)
        user = request.app.state.store.upsert_user("invite", key, name)
        return _signed_in(s, user)

    @r.post("/auth/logout")
    def logout(request: Request):
        """Clears the cookie and, for a valid session, revokes every session of the user (review #7)."""
        s: Settings = request.app.state.settings
        sess = session.verify(s.session_secret, request.cookies.get(session.COOKIE))
        if sess is not None:
            user = request.app.state.store.get_user(sess.user_id)
            if user is not None and user["session_epoch"] == sess.epoch:
                request.app.state.store.bump_session_epoch(user["id"])
        response = JSONResponse({"ok": True})
        response.delete_cookie(session.COOKIE, path="/", httponly=True, samesite="lax", secure=s.cookie_secure)
        return response

    @r.get("/me")
    def me(request: Request, user: dict = Depends(current_user)) -> dict:
        return {**user_view(user), "usage": usage_view(request.app.state.store, request.app.state.settings,
                                                        user["id"])}

    @r.get("/conversations")
    def conversations(request: Request, user: dict = Depends(current_user)) -> dict:
        store: Store = request.app.state.store
        return {"conversations": [summary_view(store, user["id"], c)
                                  for c in store.list_conversations(user["id"])]}

    @r.post("/conversations")
    async def new_conversation(request: Request, user: dict = Depends(current_user)) -> dict:
        # The contract's request is `{}`; an empty body is accepted too, anything else must be an object.
        raw = await request.body()
        if raw.strip():
            try:
                ok = isinstance(json.loads(raw), dict)
            except ValueError:
                ok = False
            if not ok:
                raise ApiError(400, "bad_request", "The request body is not valid.")
        created = await asyncio.to_thread(request.app.state.store.create_conversation, user["id"])
        return {**created, "title": created["title"] or NEW_CONVERSATION_TITLE}

    @r.get("/conversations/{conversation_id}")
    def conversation(conversation_id: str, request: Request, user: dict = Depends(current_user)) -> dict:
        summary = request.app.state.store.get_conversation(user["id"], conversation_id)
        if summary is None:
            raise ApiError(404, "not_found", "Conversation not found.")
        summary = summary_view(request.app.state.store, user["id"], summary)
        return {**summary, "messages": request.app.state.airline.messages(user["id"], conversation_id)}

    @r.post("/conversations/{conversation_id}/messages")
    async def send_message(conversation_id: str, body: Text, request: Request,
                           user: dict = Depends(current_user)):
        # Everything that can fail is decided here, before the response headers go out.
        app = request.app
        if await asyncio.to_thread(app.state.store.get_conversation, user["id"], conversation_id) is None:
            raise ApiError(404, "not_found", "Conversation not found.")
        agent: Agent | None = app.state.agent
        if agent is None:
            raise ApiError(503, "llm_unavailable", "The assistant is not configured on this server.")
        try:
            reservation = await asyncio.to_thread(reserve_message, app.state.store, app.state.settings,
                                                  user["id"], conversation_id)
        except NotFound:
            raise ApiError(404, "not_found", "Conversation not found.") from None
        try:
            events = agent.stream_turn(user["id"], conversation_id, body.text)
        except (NotFound, ValueError) as e:
            # refused before anything was stored: the slot is given back
            await asyncio.to_thread(app.state.store.release_message, user["id"], reservation)
            if isinstance(e, NotFound):
                raise ApiError(404, "not_found", "Conversation not found.") from None
            raise ApiError(400, "bad_request", str(e) or "The message is not valid.") from None
        return StreamingResponse(encode_stream(events), media_type=SSE_MEDIA_TYPE, headers=SSE_HEADERS)

    @r.post("/quotes/{quote_id}/book")
    async def book(quote_id: str, body: Nonce, request: Request, user: dict = Depends(current_user)) -> dict:
        return await request.app.state.airline.book_async(user["id"], quote_id, body.nonce)

    @r.get("/quotes/{quote_id}/trace")
    def trace(quote_id: str, request: Request, user: dict = Depends(current_user)) -> dict:
        return request.app.state.airline.trace(user["id"], quote_id)

    @r.get("/tickets")
    def tickets(request: Request, user: dict = Depends(current_user)) -> dict:
        return {"tickets": request.app.state.airline.tickets(user["id"])}

    @r.get("/debug/sse-ping")
    async def sse_ping(request: Request):
        interval = request.app.state.settings.ping_interval

        async def events():
            for seq in range(1, PING_COUNT + 1):
                if seq > 1:
                    await asyncio.sleep(interval)
                yield f"event: ping\ndata: {json.dumps({'seq': seq})}\n\n"

        return StreamingResponse(events(), media_type="text/event-stream",
                                 headers={"Cache-Control": "no-cache", "X-Accel-Buffering": "no"})

    return r


def install(app: FastAPI, settings: Settings, networks: NetworkProvider, clock=None, *,
            llm=None, agent_kwargs: dict | None = None) -> None:
    """Called from the app's lifespan: opens app.db and shares one Airline (one lock set) between
    the booking route and the agent. `llm` (tests) replaces the OpenAI-compatible client; with no
    API key configured there is no agent and the message route answers 503 llm_unavailable."""
    app.state.settings = settings
    for warning in settings.warnings():
        log.warning("config: %s", warning)
    app.state.store = store = Store(settings.app_db, **({"clock": clock} if clock else {}))
    app.state.google = GoogleVerifier(settings.google_client_id) if settings.google_client_id else None
    app.state.invite_codes = InviteCodes(settings.invite_codes)
    app.state.login_throttle = Throttle(settings.login_attempts_per_minute, 60.0)
    app.state.airline = airline = Airline(store, networks, nonce_secret=settings.nonce_secret)
    if llm is None:
        try:
            llm = OpenAIChatClient(LLMConfig.from_env(),
                                   max_tokens=settings.agent_budget.max_output_tokens_per_call)
        except LLMNotConfigured:
            llm = None
    app.state.llm = llm
    agent_kwargs = {"budget": settings.agent_budget, **(agent_kwargs or {})}
    app.state.agent = Agent(airline, llm, **agent_kwargs) if llm is not None else None


async def shutdown(app: FastAPI) -> None:
    """Let running turns finish (they are stored even when the client left), then close the LLM client."""
    if getattr(app.state, "agent", None) is not None:
        await app.state.agent.wait_idle()
    close = getattr(getattr(app.state, "llm", None), "aclose", None)
    if close is not None:
        await close()


def mount(app: FastAPI) -> None:
    install_handlers(app)
    app.add_middleware(ApiGuard)
    app.include_router(build_router())
"""Runtime settings read from the environment (never committed; see .env.example)."""
from __future__ import annotations

import os
import secrets
from dataclasses import dataclass, field
from pathlib import Path

from ..agent.budget import AgentBudget
from .logins import parse_codes, parse_networks

DEFAULT_APP_DB = Path(__file__).resolve().parents[2] / "data" / "app.db"
SESSION_TTL_SECONDS = 7 * 24 * 3600


def _flag(value: str | None) -> bool:
    return (value or "").strip().lower() in ("1", "true", "yes", "on")


@dataclass
class Settings:
    app_db: Path = DEFAULT_APP_DB
    dev_user: str = ""
    dev_password: str = field(default="", repr=False)
    cookie_secure: bool = False
    session_secret: bytes = field(default_factory=lambda: secrets.token_bytes(32), repr=False)
    nonce_secret: bytes | None = field(default=None, repr=False)
    google_client_id: str | None = None
    invite_codes: list[str] = field(default_factory=list, repr=False)
    trusted_proxies: tuple = field(default_factory=lambda: parse_networks(None))
    trust_cf_connecting_ip: bool = False  # only behind Cloudflare (review #4)
    login_attempts_per_minute: int = 10
    daily_messages_per_user: int = 50  # chat messages per user per UTC day (limits.py)
    daily_token_budget: int = 2_000_000  # site-wide sum of llm_calls.tokens per UTC day (limits.py)
    agent_budget: AgentBudget = field(default_factory=AgentBudget)  # per-turn agent budgets (AGENT_*)
    ping_interval: float = 2.0  # /api/debug/sse-ping spacing, seconds

    @property
    def dev_login(self) -> bool:
        return bool(self.dev_user and self.dev_password)

    @property
    def invite_login(self) -> bool:
        return bool(self.invite_codes)

    def warnings(self) -> list[str]:
        """Configuration mistakes worth a log line at startup (review #12)."""
        out = []
        if (self.google_client_id or self.invite_codes) and not self.cookie_secure:
            out.append("public logins are enabled but COOKIE_SECURE is off: the session cookie may be sent "
                       "over plain HTTP; set COOKIE_SECURE=1 behind HTTPS")
        return out

    @classmethod
    def from_env(cls, env=None) -> "Settings":
        env = os.environ if env is None else env
        s = cls()
        if env.get("APP_DB"):
            s.app_db = Path(env["APP_DB"])
        s.dev_user = env.get("DEV_AUTH_USER", "")
        s.dev_password = env.get("DEV_AUTH_PASSWORD", "")
        s.cookie_secure = _flag(env.get("COOKIE_SECURE"))
        # Without SESSION_SECRET a restart signs everyone out (random key per process).
        if env.get("SESSION_SECRET"):
            s.session_secret = env["SESSION_SECRET"].encode()
        if env.get("NONCE_SECRET"):
            s.nonce_secret = env["NONCE_SECRET"].encode()
        s.google_client_id = (env.get("GOOGLE_CLIENT_ID") or "").strip() or None
        s.invite_codes = parse_codes(env.get("INVITE_CODES"))
        s.trusted_proxies = parse_networks(env.get("TRUSTED_PROXIES"))
        s.trust_cf_connecting_ip = _flag(env.get("TRUST_CF_CONNECTING_IP"))
        if env.get("DAILY_MESSAGES_PER_USER", "").strip().isdigit():
            s.daily_messages_per_user = int(env["DAILY_MESSAGES_PER_USER"])
        if env.get("DAILY_TOKEN_BUDGET", "").strip().replace("_", "").isdigit():
            s.daily_token_budget = int(env["DAILY_TOKEN_BUDGET"].strip().replace("_", ""))
        s.agent_budget = AgentBudget.from_env(env)  # ValueError on a bad AGENT_* value: fail at startup
        return s

toolUseResult.stdout:
"""Per-turn budgets of the agent loop (design §4.8): LLM steps, tool calls, tokens, wall time.

`AgentBudget` is the configuration (defaults below, env overrides validated by `from_env`).
`BudgetTracker` is one turn's tally. The loop asks it before every LLM step (`stop_before_step`)
and before every tool call (`admit_tool_call`); it never executes anything itself.

Token accounting is a **soft** cap and not a dollar cap:
- the provider's `usage.total_tokens` of a call is only known after the call, so the check runs
  between LLM requests: a turn that crosses the cap finishes the call in flight and starts no
  further step;
- a call (failed or completed) that reports no usage is charged a conservative estimate:
  `ceil(request characters / CHARS_PER_TOKEN_ESTIMATE) + max_output_tokens_per_call`
  (every character of the request counted as half a token, plus the whole output allowance);
- retries are separate calls and are charged too.
"""
from __future__ import annotations

import json
import math
import os
from dataclasses import dataclass, fields
from typing import Any, Mapping

CHARS_PER_TOKEN_ESTIMATE = 2  # conservative: English text and JSON average about 3-4 characters per token

# name -> (environment variable, lowest, highest). Bounds keep a typo from removing a budget
# (0 or a huge number) or from making every turn fail.
_BOUNDS: dict[str, tuple[str, float, float]] = {
    "max_steps": ("AGENT_MAX_STEPS", 1, 20),
    "max_tool_calls_per_step": ("AGENT_MAX_TOOL_CALLS_PER_STEP", 1, 16),
    "max_tool_calls_per_turn": ("AGENT_MAX_TOOL_CALLS_PER_TURN", 1, 64),
    "max_output_tokens_per_call": ("AGENT_MAX_OUTPUT_TOKENS_PER_CALL", 256, 32_768),
    "max_total_tokens_per_turn": ("AGENT_MAX_TOTAL_TOKENS_PER_TURN", 1_000, 1_000_000),
    "max_turn_seconds": ("AGENT_MAX_TURN_SECONDS", 5, 600),
}


@dataclass(frozen=True)
class AgentBudget:
    max_steps: int = 6  # LLM steps (calls that complete, not counting retries) per turn
    max_tool_calls_per_step: int = 4  # executed tool calls of one completion
    max_tool_calls_per_turn: int = 12  # executed tool calls of the whole turn
    max_output_tokens_per_call: int = 4096  # the request's max_tokens (includes thinking tokens)
    max_total_tokens_per_turn: int = 20_000  # soft: provider-reported total tokens of all calls
    max_turn_seconds: float = 90.0  # the whole turn: LLM calls, tools, retries

    def __post_init__(self) -> None:
        for f in fields(self):
            value = getattr(self, f.name)
            whole = f.name != "max_turn_seconds"
            if isinstance(value, bool) or not isinstance(value, (int, float)) \
                    or (whole and not isinstance(value, int)) or not math.isfinite(value) or value <= 0:
                raise ValueError(f"{f.name} must be a positive {'integer' if whole else 'number'}, got {value!r}")

    def checked(self) -> "AgentBudget":
        """The same budget, also within the bounds the environment may set (startup check)."""
        for name, (var, low, high) in _BOUNDS.items():
            value = getattr(self, name)
            if not low <= value <= high:
                raise ValueError(f"{var} must be between {low:g} and {high:g}, got {value:g}")
        return self

    @classmethod
    def from_env(cls, env: Mapping[str, str] | None = None) -> "AgentBudget":
        """Defaults, overridden by the `AGENT_*` variables of `_BOUNDS`. A value that is not a
        number or is out of bounds raises ValueError (the app does not start with a bad budget)."""
        env = os.environ if env is None else env
        values: dict[str, Any] = {}
        for name, (var, low, high) in _BOUNDS.items():
            raw = (env.get(var) or "").strip().replace("_", "")
            if not raw:
                continue
            try:
                value = float(raw) if name == "max_turn_seconds" else int(raw)
            except ValueError:
                raise ValueError(f"{var} must be {'a number' if name == 'max_turn_seconds' else 'an integer'}, "
                                 f"got {raw!r}") from None
            if not low <= value <= high:  # also catches nan
                raise ValueError(f"{var} must be between {low:g} and {high:g}, got {raw!r}")
            values[name] = value
        return cls(**values).checked()


def estimate_tokens(messages: Any, max_output_tokens: int) -> int:
    """Conservative charge for a call without reported usage (see the module docstring)."""
    chars = len(json.dumps(messages, ensure_ascii=False, separators=(",", ":"), default=str))
    return math.ceil(chars / CHARS_PER_TOKEN_ESTIMATE) + max_output_tokens


def reported_tokens(usage: Any) -> int | None:
    """`usage.total_tokens` when the provider reported a usable one."""
    total = usage.get("total_tokens") if isinstance(usage, dict) else None
    if isinstance(total, bool) or not isinstance(total, int) or total < 0:
        return None
    return total


class BudgetTracker:
    """One turn's use of an `AgentBudget`. Not thread-safe; owned by the turn's task."""

    def __init__(self, budget: AgentBudget):
        self.budget = budget
        self.steps = 0  # LLM steps started
        self.tool_calls = 0  # tool calls executed (refused ones not counted)
        self.refused_calls = 0
        self.tokens = 0  # reported + estimated
        self.estimated_calls = 0  # calls charged by estimate
        self._step_calls = 0

    # ---------------------------------------------------------------- LLM steps ------------
    def stop_before_step(self) -> dict | None:
        """None when another LLM step may start (and counts it), else the fallback problem."""
        if self.steps >= self.budget.max_steps:
            return {"kind": "max_steps", "value": str(self.budget.max_steps)}
        if self.tokens >= self.budget.max_total_tokens_per_turn:
            return {"kind": "token_budget", "value": str(self.budget.max_total_tokens_per_turn)}
        self.steps += 1
        self._step_calls = 0
        return None

    def charge(self, usage: Any, request_messages: Any) -> tuple[int, bool]:
        """Count one LLM call (completed, failed or retried). Returns (tokens charged, estimated)."""
        total = reported_tokens(usage)
        if total is None:
            total = estimate_tokens(request_messages, self.budget.max_output_tokens_per_call)
            self.estimated_calls += 1
            self.tokens += total
            return total, True
        self.tokens += total
        return total, False

    # ---------------------------------------------------------------- tool calls -----------
    def admit_tool_call(self) -> str | None:
        """None when one more tool call of the current step may run (and counts it), else why
        not: "per_step" or "per_turn". A refused call is never executed."""
        if self.tool_calls >= self.budget.max_tool_calls_per_turn:
            reason = "per_turn"
        elif self._step_calls >= self.budget.max_tool_calls_per_step:
            reason = "per_step"
        else:
            self.tool_calls += 1
            self._step_calls += 1
            return None
        self.refused_calls += 1
        return reason

    @property
    def tool_calls_left(self) -> int:
        return self.budget.max_tool_calls_per_turn - self.tool_calls

    def snapshot(self) -> dict:
        """For logs and the llm_calls record (no secrets, small)."""
        return {"steps": self.steps, "tool_calls": self.tool_calls, "refused_calls": self.refused_calls,
                "tokens": self.tokens, "estimated_calls": self.estimated_calls}


def refusal(reason: str, budget: AgentBudget) -> dict:
    """The tool result of a call that was not executed (the LLM protocol needs one per call)."""
    if reason == "per_step":
        message = (f"Not executed: at most {budget.max_tool_calls_per_step} tool calls are run per step. "
                   "Call the remaining tools again in a later step if they are still needed.")
    else:
        message = (f"Not executed: this turn has used all {budget.max_tool_calls_per_turn} tool calls. "
                   "Answer with the results you already have.")
    return {"code": "tool_budget_exceeded", "message": message, "limit": reason}
"""All endpoints of docs/api/contract.md except the message stream (501 until T3 is merged)."""
from __future__ import annotations

import asyncio
import hmac
import json
import logging
import math

from fastapi import APIRouter, Depends, FastAPI, Request
from fastapi.responses import JSONResponse, StreamingResponse
from typing import Annotated

from pydantic import AfterValidator, BaseModel

from ..agent import Agent, LLMConfig, LLMNotConfigured, OpenAIChatClient, encode_stream
from ..agent.loop import MAX_USER_CHARS, TITLE_CHARS
from ..agent.sse import HEADERS as SSE_HEADERS, MEDIA_TYPE as SSE_MEDIA_TYPE
from ..airline import Airline, NotFound
from ..core.network import NetworkProvider
from ..store import Store
from . import session
from .google import MAX_TOKEN_CHARS, GoogleVerifier, InvalidToken, KeysUnavailable
from .logins import InviteCodes, Throttle, clean_name, client_ip, throttle_key
from .errors import ApiError, install_handlers, respond
from .guards import ApiGuard
from .limits import reserve_message, usage_view
from .settings import SESSION_TTL_SECONDS, Settings

PING_COUNT = 5
NEW_CONVERSATION_TITLE = "New conversation"
GOOGLE_NAME_MAX = 80

log = logging.getLogger(__name__)


# Field bounds (review #11): oversized values are a 400 before any hashing or lookup. The message
# text bound is generous; the agent's own MAX_USER_CHARS check keeps its specific message.
# (An after-validator, not Field(max_length): pydantic's constraint path refuses lone surrogates,
# which must stay a wrong login, not a 400.)
SHORT_FIELD = 200


def _bounded(limit: int):
    def check(value: str) -> str:
        if len(value) > limit:
            raise ValueError("too long")
        return value
    return Annotated[str, AfterValidator(check)]


class Credentials(BaseModel):
    username: _bounded(SHORT_FIELD)
    password: _bounded(SHORT_FIELD)


class GoogleCredential(BaseModel):
    credential: _bounded(MAX_TOKEN_CHARS)


class Invite(BaseModel):
    code: _bounded(SHORT_FIELD)
    name: _bounded(SHORT_FIELD)


class Text(BaseModel):
    text: _bounded(4 * MAX_USER_CHARS)


class Nonce(BaseModel):
    nonce: _bounded(SHORT_FIELD)


def login_enabled(request: Request, user: dict) -> bool:
    """Is the way this user signed in still switched on? (review #7: turning dev login off or
    removing an invite code ends those sessions, not only new logins)"""
    s: Settings = request.app.state.settings
    provider = user["auth_provider"]
    if provider == "dev":
        return s.dev_login  # renaming DEV_AUTH_USER does not end the old user's sessions: rotate SESSION_SECRET
    if provider == "invite":
        return request.app.state.invite_codes.active(user["provider_sub"])
    if provider == "google":
        return request.app.state.google is not None
    return False


def current_user(request: Request) -> dict:
    """The signed-in user, or 401. The cookie names the user and its session epoch; the row must
    still exist, the epoch must be current (not logged out since) and the login method enabled."""
    s: Settings = request.app.state.settings
    sess = session.verify(s.session_secret, request.cookies.get(session.COOKIE))
    user = request.app.state.store.get_user(sess.user_id) if sess else None
    if user is None or user["session_epoch"] != sess.epoch or not login_enabled(request, user):
        raise ApiError(401, "unauthorized", "Please sign in.")
    return user


def _octets(text: str) -> bytes:
    return text.encode("utf-8", "surrogatepass")


def user_view(user: dict) -> dict:
    return {"id": user["id"], "display_name": user["display_name"], "auth_provider": user["auth_provider"],
            "email": user["email"]}


def summary_view(store: Store, user_id: str, summary: dict) -> dict:
    """Contract: the title is never empty — first user message, else "New conversation"."""
    if summary["title"].strip():
        return summary
    first = " ".join(store.first_user_text(user_id, summary["id"]).split())[:TITLE_CHARS]
    return {**summary, "title": first or NEW_CONVERSATION_TITLE}


def throttle_login(request: Request) -> None:
    """Login endpoints: at most N attempts per client IP per minute (contract), else 429."""
    s: Settings = request.app.state.settings
    ip = client_ip(request.client.host if request.client else None, request.headers, s.trusted_proxies,
                   s.trust_cf_connecting_ip)
    wait = request.app.state.login_throttle.hit(throttle_key(ip))
    if wait is not None:
        raise ApiError(429, "rate_limited", "Too many sign-in attempts. Please wait a minute and try again.",
                       headers={"Retry-After": str(max(1, math.ceil(wait)))})


def _signed_in(settings: Settings, user: dict) -> JSONResponse:
    response = JSONResponse(user_view(user))
    _set_cookie(response, settings, user["id"], user["session_epoch"])
    return response


def _set_cookie(response, settings: Settings, user_id: str, epoch: int) -> None:
    response.set_cookie(session.COOKIE, session.issue(settings.session_secret, user_id, SESSION_TTL_SECONDS,
                                                      epoch=epoch),
                        max_age=SESSION_TTL_SECONDS, httponly=True, samesite="lax",
                        secure=settings.cookie_secure, path="/")


def build_router() -> APIRouter:
    r = APIRouter(prefix="/api")

    @r.get("/health")
    def health(request: Request) -> dict:
        net = request.app.state.networks.current()
        return {"status": "ok", "network_fingerprint": net.fingerprint.id}

    @r.get("/config")
    def config(request: Request) -> dict:
        s: Settings = request.app.state.settings
        return {"dev_login": s.dev_login, "invite_login": s.invite_login, "google_client_id": s.google_client_id}

    @r.post("/auth/dev")
    def auth_dev(creds: Credentials, request: Request):
        s: Settings = request.app.state.settings
        if not s.dev_login:
            raise ApiError(404, "not_found", "Not found.")
        throttle_login(request)
        # surrogatepass: a lone surrogate in the JSON must be a wrong password, not a 500
        ok = s.dev_login and hmac.compare_digest(_octets(creds.username), _octets(s.dev_user)) \
            & hmac.compare_digest(_octets(creds.password), _octets(s.dev_password))
        if not ok:
            raise ApiError(401, "invalid_credentials", "Wrong username or password.")
        user = request.app.state.store.upsert_user("dev", s.dev_user, s.dev_user)
        return _signed_in(s, user)

    @r.post("/auth/google")
    def auth_google(body: GoogleCredential, request: Request):
        s: Settings = request.app.state.settings
        verifier: GoogleVerifier | None = request.app.state.google
        if verifier is None:
            raise ApiError(404, "not_found", "Not found.")
        throttle_login(request)
        try:
            who = verifier.verify(body.credential)
        except KeysUnavailable:
            raise ApiError(503, "auth_unavailable",
                           "Google sign-in is unavailable right now. Please try again later.") from None
        except InvalidToken as e:
            log.info("google sign-in rejected: %s", e)  # the reason only, never the token
            raise ApiError(401, "invalid_credentials", "Google sign-in could not be verified.") from None
        name = " ".join((who.name or who.email or "Google user").split())[:GOOGLE_NAME_MAX] or "Google user"
        user = request.app.state.store.upsert_user("google", who.sub, name, who.email)
        return _signed_in(s, user)

    @r.post("/auth/invite")
    def auth_invite(body: Invite, request: Request):
        s: Settings = request.app.state.settings
        codes: InviteCodes = request.app.state.invite_codes
        if not codes:
            raise ApiError(404, "not_found", "Not found.")
        throttle_login(request)
        key = codes.match(body.code)
        if key is None:
            raise ApiError(401, "invalid_credentials", "That invite code is not valid.")
        name = clean_name(body.name)
        if name is None:
            raise ApiError(400, "bad_request", "The name must be 1–40 characters.")
        # one account per code; the name is only the display name (refreshed on every login)
        user = request.app.state.store.upsert_user("invite", key, name)
        return _signed_in(s, user)

    @r.post("/auth/logout")
    def logout(request: Request):
        """Clears the cookie and, for a valid session, revokes every session of the user (review #7)."""
        s: Settings = request.app.state.settings
        sess = session.verify(s.session_secret, request.cookies.get(session.COOKIE))
        if sess is not None:
            user = request.app.state.store.get_user(sess.user_id)
            if user is not None and user["session_epoch"] == sess.epoch:
                request.app.state.store.bump_session_epoch(user["id"])
        response = JSONResponse({"ok": True})
        response.delete_cookie(session.COOKIE, path="/", httponly=True, samesite="lax", secure=s.cookie_secure)
        return response

    @r.get("/me")
    def me(request: Request, user: dict = Depends(current_user)) -> dict:
        return {**user_view(user), "usage": usage_view(request.app.state.store, request.app.state.settings,
                                                        user["id"])}

    @r.get("/conversations")
    def conversations(request: Request, user: dict = Depends(current_user)) -> dict:
        store: Store = request.app.state.store
        return {"conversations": [summary_view(store, user["id"], c)
                                  for c in store.list_conversations(user["id"])]}

    @r.post("/conversations")
    async def new_conversation(request: Request, user: dict = Depends(current_user)) -> dict:
        # The contract's request is `{}`; an empty body is accepted too, anything else must be an object.
        raw = await request.body()
        if raw.strip():
            try:
                ok = isinstance(json.loads(raw), dict)
            except ValueError:
                ok = False
            if not ok:
                raise ApiError(400, "bad_request", "The request body is not valid.")
        created = await asyncio.to_thread(request.app.state.store.create_conversation, user["id"])
        return {**created, "title": created["title"] or NEW_CONVERSATION_TITLE}

    @r.get("/conversations/{conversation_id}")
    def conversation(conversation_id: str, request: Request, user: dict = Depends(current_user)) -> dict:
        summary = request.app.state.store.get_conversation(user["id"], conversation_id)
        if summary is None:
            raise ApiError(404, "not_found", "Conversation not found.")
        summary = summary_view(request.app.state.store, user["id"], summary)
        return {**summary, "messages": request.app.state.airline.messages(user["id"], conversation_id)}

    @r.post("/conversations/{conversation_id}/messages")
    async def send_message(conversation_id: str, body: Text, request: Request,
                           user: dict = Depends(current_user)):
        # Everything that can fail is decided here, before the response headers go out.
        app = request.app
        if await asyncio.to_thread(app.state.store.get_conversation, user["id"], conversation_id) is None:
            raise ApiError(404, "not_found", "Conversation not found.")
        agent: Agent | None = app.state.agent
        if agent is None:
            raise ApiError(503, "llm_unavailable", "The assistant is not configured on this server.")
        try:
            reservation = await asyncio.to_thread(reserve_message, app.state.store, app.state.settings,
                                                  user["id"], conversation_id)
        except NotFound:
            raise ApiError(404, "not_found", "Conversation not found.") from None
        try:
            events = agent.stream_turn(user["id"], conversation_id, body.text)
        except (NotFound, ValueError) as e:
            # refused before anything was stored: the slot is given back
            await asyncio.to_thread(app.state.store.release_message, user["id"], reservation)
            if isinstance(e, NotFound):
                raise ApiError(404, "not_found", "Conversation not found.") from None
            raise ApiError(400, "bad_request", str(e) or "The message is not valid.") from None
        return StreamingResponse(encode_stream(events), media_type=SSE_MEDIA_TYPE, headers=SSE_HEADERS)

    @r.post("/quotes/{quote_id}/book")
    async def book(quote_id: str, body: Nonce, request: Request, user: dict = Depends(current_user)) -> dict:
        return await request.app.state.airline.book_async(user["id"], quote_id, body.nonce)

    @r.get("/quotes/{quote_id}/trace")
    def trace(quote_id: str, request: Request, user: dict = Depends(current_user)) -> dict:
        return request.app.state.airline.trace(user["id"], quote_id)

    @r.get("/tickets")
    def tickets(request: Request, user: dict = Depends(current_user)) -> dict:
        return {"tickets": request.app.state.airline.tickets(user["id"])}

    @r.get("/debug/sse-ping")
    async def sse_ping(request: Request):
        interval = request.app.state.settings.ping_interval

        async def events():
            for seq in range(1, PING_COUNT + 1):
                if seq > 1:
                    await asyncio.sleep(interval)
                yield f"event: ping\ndata: {json.dumps({'seq': seq})}\n\n"

        return StreamingResponse(events(), media_type="text/event-stream",
                                 headers={"Cache-Control": "no-cache", "X-Accel-Buffering": "no"})

    return r


def install(app: FastAPI, settings: Settings, networks: NetworkProvider, clock=None, *,
            llm=None, agent_kwargs: dict | None = None) -> None:
    """Called from the app's lifespan: opens app.db and shares one Airline (one lock set) between
    the booking route and the agent. `llm` (tests) replaces the OpenAI-compatible client; with no
    API key configured there is no agent and the message route answers 503 llm_unavailable."""
    app.state.settings = settings
    for warning in settings.warnings():
        log.warning("config: %s", warning)
    app.state.store = store = Store(settings.app_db, **({"clock": clock} if clock else {}))
    app.state.google = GoogleVerifier(settings.google_client_id) if settings.google_client_id else None
    app.state.invite_codes = InviteCodes(settings.invite_codes)
    app.state.login_throttle = Throttle(settings.login_attempts_per_minute, 60.0)
    app.state.airline = airline = Airline(store, networks, nonce_secret=settings.nonce_secret)
    if llm is None:
        try:
            llm = OpenAIChatClient(LLMConfig.from_env(),
                                   max_tokens=settings.agent_budget.max_output_tokens_per_call)
        except LLMNotConfigured:
            llm = None
    app.state.llm = llm
    agent_kwargs = {"budget": settings.agent_budget, **(agent_kwargs or {})}
    app.state.agent = Agent(airline, llm, **agent_kwargs) if llm is not None else None


async def shutdown(app: FastAPI) -> None:
    """Let running turns finish (they are stored even when the client left), then close the LLM client."""
    if getattr(app.state, "agent", None) is not None:
        await app.state.agent.wait_idle()
    close = getattr(getattr(app.state, "llm", None), "aclose", None)
    if close is not None:
        await close()


def mount(app: FastAPI) -> None:
    install_handlers(app)
    app.add_middleware(ApiGuard)
    app.include_router(build_router())
"""Runtime settings read from the environment (never committed; see .env.example)."""
from __future__ import annotations

import os
import secrets
from dataclasses import dataclass, field
from pathlib import Path

from ..agent.budget import AgentBudget
from .logins import parse_codes, parse_networks

DEFAULT_APP_DB = Path(__file__).resolve().parents[2] / "data" / "app.db"
SESSION_TTL_SECONDS = 7 * 24 * 3600


def _flag(value: str | None) -> bool:
    return (value or "").strip().lower() in ("1", "true", "yes", "on")


@dataclass
class Settings:
    app_db: Path = DEFAULT_APP_DB
    dev_user: str = ""
    dev_password: str = field(default="", repr=False)
    cookie_secure: bool = False
    session_secret: bytes = field(default_factory=lambda: secrets.token_bytes(32), repr=False)
    nonce_secret: bytes | None = field(default=None, repr=False)
    google_client_id: str | None = None
    invite_codes: list[str] = field(default_factory=list, repr=False)
    trusted_proxies: tuple = field(default_factory=lambda: parse_networks(None))
    trust_cf_connecting_ip: bool = False  # only behind Cloudflare (review #4)
